import {appLanguage} from './language.mjs';
import {nextPathLesson} from './learning-path.mjs';
import {wordClassLabel} from './word-class-labels.mjs';
import {h,icon,button as btn,plural,highlightText,pronounce,spoken,teachingText} from './ui.mjs';
import {lessonById,isMarked,lessons} from './course.mjs';
import {normalize,activeStreak} from './engine.mjs';
import {renderMemoryResult} from './memory-view.mjs';
import {renderIllustration} from './illustrations.mjs';
import {modeNames} from './views.mjs';
import {recommendLesson} from './lesson-navigation.mjs';
import {compareDictation,annotate} from './pd3-diff.mjs';
import {SPELL_FREE_LISTENS} from './pd3-spell.mjs';

export function hasAnswer(session){const t=session?.tasks[session.index];return t?.kind==='build'?session.words.length>0:!!session?.answer.trim();}

// ---- Dictation cards (kind 'dictate', see learning.mjs and pd3-spell.mjs) -----------------------------------------
const MARK_TEXT={misspelled:'написано с ошибкой',missing:'пропущено',order:'не на своём месте',extra:'лишнее'};
/** The counter of listenings under the play button; the app updates it in place after a listening. */
export const playsText=plays=>plays<1?'':plays>SPELL_FREE_LISTENS?`Прослушано: ${plays} · засчитано как подсказка`:`Прослушано: ${plays}`;
const marked=pieces=>pieces.map(piece=>piece.status&&piece.status!=='correct'?`<span class="pd3-d-${piece.status}">${h(piece.text)}<span class="sr-only"> (${MARK_TEXT[piece.status]||piece.status})</span></span>`:h(piece.text)).join('')||'<i>(пусто)</i>';
function dictationPrompt(session,t,p){
 if(t.dictMode==='cloze')return `<div class="exercise-prompt"><span class="pill purple">DA</span><p lang="da">${h(t.prompt).replace(/___/g,'<span class="gap-slot">…</span>')}</p>${session.submitted?`<button class="icon-button" data-action="listen" title="Послушать фразу">${icon('sound')}</button>`:''}</div><p class="gap-meaning">${h(p.ru)}</p>`;
 return `<div class="listening-prompt dictation-listen"><button class="sound-play" data-action="listen" title="Послушать предложение">${icon('sound')}</button><div><b>Послушай и запиши предложение</b><button class="text-button" data-action="listen-slow">Послушать медленнее</button><small class="dictation-plays" data-plays role="status">${h(playsText(session.plays||0))}</small></div></div>${session.submitted?'':`<p class="field-note">Первое прослушивание — без подсказки, каждое следующее считается подсказкой. Регистр и знаки препинания не важны.</p><button class="text-button" data-action="dictate-cloze">Нет звука · показать с пропуском</button>`}`;
}
function dictationFeedback(session,t,p){
 const help=session.helped||session.revealed;
 const heading=session.feedback?help?'С подсказкой. Проверим позже.':'Верно.':'Запомним этот момент.';
 let body;
 if(t.dictMode==='cloze')body=`${session.feedback?'':`<p>Пропущенное слово: <b lang="da">${h(t.answers[0])}</b></p>`}<p lang="da" class="complete-example">${h(p.da)}</p>`;
 else{
  const result=compareDictation(t.answers[0],session.answer||'');
  body=`<p class="dictation-label">Эталон</p><p lang="da" class="complete-example dictation-reference">${marked(annotate(t.answers[0],result.ref))}</p>${session.feedback?'':`<p class="dictation-label">Твой ответ</p><p lang="da" class="dictation-typed">${marked(annotate(session.answer||'',result.user))}</p>`}`;
 }
 return `<section class="answer-feedback ${session.feedback?'good':'bad'}" role="status"><div class="feedback-heading">${icon(session.feedback?'check':'info')}<h3>${heading}</h3></div>${body}<details class="hint dictation-translation"><summary>${icon('info')} Показать перевод</summary><p>${h(p.ru)}</p></details>${btn(`${icon('sound')} Слушать ещё раз`,'listen','secondary')}${btn('Произнести и сравнить','pronounce-answer','secondary',`data-text="${h(p.da)}"`)}</section>`;
}

export function exerciseView(session,catalog,state){
 const t=session.tasks[session.index],p=catalog[t.itemId],l=lessonById[p.lessonId],listening=t.kind==='listen'&&!session.revealed;
 const title=t.kind==='dictate'?(t.dictMode==='cloze'?'Вставь пропущенное слово':'Послушай и напиши'):p.dialogue?(t.kind==='build'?'Собери ответ собеседнику':t.kind==='choice'?'Выбери ответ по ситуации':'Ответь собеседнику по-датски'):t.kind==='focus'?t.question:t.kind==='build'?'Собери датскую фразу':t.kind==='gap'?'Вставь нужную форму':listening?'Послушай и выбери смысл':t.kind==='type'?`Напиши ${t.answerLang==='da'?'по-датски':'по-русски'}`:'Выбери подходящий перевод';
 const prompt=t.kind==='dictate'?dictationPrompt(session,t,p):listening?`<div class="listening-prompt"><button class="sound-play" data-action="listen" title="Послушать фразу">${icon('sound')}</button><div><b>Что ты услышал?</b><button class="text-button" data-action="listen-slow">Послушать медленнее</button></div><button class="text-button" data-action="reveal">Показать текст</button></div>`:`<div class="exercise-prompt"><span class="pill ${t.promptLang==='da'?'purple':'blue'}">${t.promptLang==='ru'?appLanguage.toUpperCase():t.promptLang.toUpperCase()}</span><p lang="${t.promptLang==='ru'?appLanguage:t.promptLang}">${highlightText(t.prompt,t.target).replace(/___/g,'<span class="gap-slot">…</span>')}</p>${t.promptLang==='da'?`<button class="icon-button" data-action="listen" title="Послушать фразу">${icon('sound')}</button>`:''}</div>`;
 const dialogue=p.dialogue?`<section class="dialogue-context" aria-label="Ситуация диалога"><p class="dialogue-situation">${h(p.dialogue.situation)}</p><div class="dialogue-partner"><small>Собеседник</small><p>${spoken(p.dialogue.partnerDa)}</p></div><details class="hint dialogue-translation"><summary>${icon('info')} Перевод реплики</summary><p>${h(p.dialogue.partnerRu)}</p></details></section>`:'';
 const model=p.dialogue?`<div class="dialogue-model"><small>Вариант ответа</small><p>${spoken(p.da)}</p><p class="muted">${h(p.ru)}</p>${p.daAnswers?.length>1?`<details class="hint"><summary>Ещё один вариант</summary><p>${spoken(p.daAnswers[1])}</p></details>`:''}</div>`:'';
 let answer;
 if(t.kind==='build')answer=`<div class="answer-zone" aria-label="Собранное предложение">${session.words.length?session.words.map((i,pos)=>`<button class="token" data-action="remove-token" data-source="answer" data-pos="${pos}" ${session.submitted?'disabled':''} lang="da" title="Убрать слово; стрелками можно менять порядок">${icon('grip')}${h(t.bank[i])}</button>`).join(''):'<span>Перетащи слова сюда или нажимай на них</span>'}</div><div class="token-bank" aria-label="Слова для предложения">${t.bank.map((word,i)=>`<span class="token-unit"><button class="token ${session.words.includes(i)?'used':''}" data-action="add-token" data-source="bank" data-pos="${i}" ${session.submitted||session.words.includes(i)?'disabled':''} lang="da">${icon('grip')}${h(word)}</button>${pronounce(word,'Послушать слово')}</span>`).join('')}</div>`;
 else if(t.options.length)answer=`<div class="answer-options" role="group" aria-label="Варианты ответа">${t.options.map((v,i)=>`<div class="answer-option-row"><button class="answer-option ${session.answer===v?'selected':''} ${session.submitted&&t.answers.some(a=>normalize(a)===normalize(v))?'correct':''} ${session.submitted&&!session.feedback&&session.answer===v?'incorrect':''}" data-action="choose" data-value="${h(v)}" aria-pressed="${session.answer===v}" ${session.submitted?'disabled':''}><span class="option-number">${i+1}</span><span lang="${t.answerLang==='ru'?appLanguage:t.answerLang}">${h(v)}</span>${session.answer===v?icon('check'):''}</button>${t.answerLang==='da'?pronounce(v,'Послушать вариант'):''}</div>`).join('')}</div>`;
 else answer=`<label for="answer-input" class="answer-label">Твой ответ</label><input id="answer-input" class="answer-input" type="text" lang="${t.answerLang==='ru'?appLanguage:t.answerLang}" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" enterkeyhint="done" maxlength="1500" placeholder="${t.answerLang==='da'?'Skriv på dansk…':'Напиши перевод…'}" value="${h(session.answer)}" ${session.submitted?'disabled':''}>${t.answerLang==='da'?`<div class="danish-keys">${['æ','ø','å'].map(letter=>`<button data-action="letter" data-letter="${letter}" ${session.submitted?'disabled':''}>${letter}</button>`).join('')}</div>`:''}`;
 const formHelp=p.formHelp?.length&&(session.mode!=='expert'||session.submitted)?`<details class="hint form-help" data-help="forms"><summary>${icon('layers')} Какие формы бывают</summary><div class="form-help-grid">${p.formHelp.map(f=>`<div><small>${h(f.label)}</small>${f.label==='Контекст'?teachingText(f.text):spoken(f.text)}</div>`).join('')}</div></details>`:'';
 const feedback=session.submitted&&t.kind==='dictate'?dictationFeedback(session,t,p):session.submitted?`<section class="answer-feedback ${session.selfChecked?'self-checked':session.feedback?'good':'bad'}" role="status"><div class="feedback-heading">${icon(session.feedback?'check':'info')}<h3>${session.selfChecked?'Самопроверка отмечена.':session.feedback?session.helped||session.revealed?'С подсказкой. Проверим позже.':'Верно.':'Запомним этот момент.'}</h3></div>${!session.feedback||session.selfChecked?`<p>Подходящий ответ: <b lang="${t.answerLang==='ru'?appLanguage:t.answerLang}">${h(t.answers[0])}</b></p>`:''}${renderIllustration(p)}${model}<p>${teachingText(p.note||'Сопоставь датскую фразу с переводом и произнеси её ещё раз.')}</p>${t.kind==='gap'?`<p lang="da" class="complete-example">${h(t.completeDa||p.da)}</p>`:t.kind==='focus'?`<p class="context-translation">${h(p.ru)}</p>`:''}${p.association?`<div class="association">${icon('brain')}<p>${h(p.association)}</p></div>`:''}${session.mode==='auto'?`<p class="own-phrase">${icon('chat')} Произнеси свою короткую фразу или измени одну деталь примера. Эта часть — для практики, без оценки.</p>`:''}${btn('Произнести и сравнить','pronounce-answer','secondary',`data-text="${h(t.completeDa||p.da)}"`)}${!session.feedback&&!t.options.length&&session.answer?.trim()?'<div class="answer-comparison"><p>Другая формулировка может быть верной. Сравни смысл, грамматику и форму с образцом.</p><button class="text-button" data-action="self-check">Мой вариант равнозначен · отметить самопроверку</button></div>':''}${session.selfChecked?'<p>Этот ответ отмечен тобой после сравнения. Он не добавляет XP или автоматический балл и вернётся к повторению через 10 минут.</p>':''}</section>`:l&&session.mode!=='expert'?`<details class="hint"><summary>${icon('layers')} Вспомнить правило</summary><p>${teachingText(l.rule)}</p></details>`:p.association?`<details class="hint"><summary>${icon('brain')} Ассоциация</summary><p>${h(p.association)}</p></details>`:'';
 return `<main class="session-shell"><header class="session-header"><button class="icon-button" data-action="pause-request" title="Сохранить и выйти">${icon('close')}</button><div class="session-meter"><div class="meter" role="progressbar" aria-label="Ход занятия" aria-valuenow="${session.index}" aria-valuemax="${session.tasks.length}" aria-valuemin="0"><span style="width:${session.index/session.tasks.length*100}%"></span></div><span>${h(session.title)}</span></div><b>${session.index+1}<small> / ${session.tasks.length}</small></b></header><div class="exercise"><div class="exercise-meta"><span class="pill purple">${l?.level||(p.kind==='dictation'?'ДИКТАНТ-КАРТОЧКА':'МОИ СЛОВА')}</span><span>${session.mode==='auto'?({recognition:'Узнать',build:'Собрать',recall:'Вспомнить'})[t.stage]||'Практика памяти':modeNames[session.mode]}</span>${t.retry?'<span class="pill peach">Ещё раз после ошибки</span>':''}</div><h1>${h(title)}</h1>${wordClassLabel(p.wordClass)&&(p.kind!=='wordclass'||session.submitted)?`<div class="word-class-name">${teachingText(wordClassLabel(p.wordClass))}</div>`:''}${p.formLabel?`<p class="form-request">${icon('info')}${h(p.formLabel)}</p>`:''}${t.hint?`<p class="form-request">${icon('info')}${h(t.hint==='article'?'С артиклем: en/et':'Глагол: at можно не писать')}</p>`:''}${dialogue}${prompt}${p.dialogue&&!session.submitted&&t.kind==='type'?'<p class="dialogue-grading field-note">Напиши целый ответ. Другую верную формулировку можно отметить самопроверкой после сравнения.</p>':''}${t.kind==='gap'?`<p class="gap-meaning">${h(t.contextTranslation||p.ru)}</p>`:''}${answer}${formHelp}${feedback}${!session.submitted?'<button class="give-up" data-action="give-up">Не помню · показать ответ</button>':''}<div class="exercise-tools"><button class="remember-button ${isMarked(p,state.difficult)?'active':''}" data-action="difficult" data-id="${p.id}" aria-pressed="${isMarked(p,state.difficult)}">${icon(isMarked(p,state.difficult)?'check':'brain')}${isMarked(p,state.difficult)?'В сложных':'Не запомнил'}</button><button class="remember-button ${isMarked(p,state.bookmarks)?'active':''}" data-action="bookmark" data-id="${p.id}" aria-pressed="${isMarked(p,state.bookmarks)}">${icon('bookmark')}${isMarked(p,state.bookmarks)?'Сохранено':'Сохранить'}</button></div><footer class="exercise-footer"><small>${session.submitted?'Разбор остаётся перед тобой до следующего задания.':t.kind==='build'?'Перетаскивай, нажимай или выбирай слова клавиатурой.':'Enter — проверить ответ.'}</small>${btn(`${session.submitted?'Продолжить':'Проверить'} ${icon('arrow')}`,session.submitted?'next-task':'check-answer','primary',!session.submitted&&!hasAnswer(session)?'disabled':'')}</footer></div></main>`;
}

export function resultView(session,state,awards){const accuracy=Math.round(session.correct/session.initialCount*100),current=lessonById[session.lessonId],next=session.route?nextPathLesson(lessons,state,session.routeLevel||current?.level):current?recommendLesson(current.roleplay?lessons.filter(l=>l.roleplay):lessons,state,{kind:current.kind,level:current.level}):null;return `<main class="session-shell"><section class="result"><div class="result-art">${icon('trophy')}<span>${icon('spark')}</span></div><span class="eyebrow">GODT KLARET</span><h1>${accuracy===100?'Чистая работа.':'Практика засчитана.'}</h1><p>${h(session.title)}</p><div class="result-stat-grid"><div class="mint"><b>+${session.correct*10}</b><span>XP</span></div><div class="purple"><b>${accuracy}%</b><span>${session.outcomes?.some(o=>o.selfChecked)?'совпало с образцом':'с первой попытки'}</span></div><div class="peach"><b>${activeStreak(state)}</b><span>${plural(activeStreak(state),['день','дня','дней'])} подряд</span></div></div>${awards.length?`<div class="new-awards">${awards.map(b=>`<div>${icon(b.icon)}<span><small>Новое достижение</small><b>${h(b.title)}</b></span></div>`).join('')}</div>`:''}<p class="result-note">${session.missed.length?'Ошибки вернулись в конце занятия. Неправильные ответы назначаются к повторению через 10 минут.':'Фразы сохранены в повторении. Следующая проверка — по расписанию.'}</p>${renderMemoryResult(session,state)}${next?btn(`${session.route&&next.id===current?.id?'Закрепить тему: ':'Следующий урок: '}${h(next.title)}`,session.route?'next-route':'next-lesson','primary',`data-id="${next.id}"`):''}${btn('Вернуться к маршруту','finish','secondary')}${btn('Мой прогресс','finish-progress','secondary')}</section></main>`;}
